export function getPageDataThunk(
  layout: string,
  page: number,
): () => unknown {
  const thunk = pageDataThunks[layout]?.[page];
  if (!thunk) throw new Error(`Page thunk not found: ${layout}/${page}`);
  return thunk;
}
